"""Build a portable icon and contact preview using the existing motion engine."""
from pathlib import Path
import json
f=Path(__file__).resolve().parent
icons=json.loads((f/'manifest.json').read_text())
for e in icons:e['svg']=(f/Path(e['file']).name).read_text()
models=json.loads((f/'assembly-models.json').read_text())
engine=(f.parents[2]/'scripts/domain-motion.js').read_text()
template='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PI3K–AKT–mTOR · 新版图标</title><style>
*{box-sizing:border-box}body{margin:0;background:#f6f9f7;color:#28474b;font:15px/1.7 Arial,sans-serif}main{max-width:1200px;margin:auto;padding:32px 24px}h1{font-size:32px;line-height:1.3}h2{font-size:23px}h3{font-size:17px;margin:10px 0}p{max-width:850px}a{color:#276d73}button{font:inherit;color:inherit;background:white;border:1px solid #b9ceca;padding:7px 16px;border-radius:5px;cursor:pointer}button[aria-pressed=true]{background:#dbece6}.toolbar{display:flex;gap:12px;align-items:center;flex-wrap:wrap;margin:24px 0}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.card{padding:18px;background:white;border:1px solid #d2dfda;border-radius:9px;min-width:0}.art{height:170px;display:flex;align-items:center;justify-content:center}.art img{width:160px;height:160px}.card p{font-size:14px;margin:8px 0}.links{display:flex;gap:16px;flex-wrap:wrap;font-size:14px}.assembly{display:grid;grid-template-columns:1fr 1fr;gap:16px}.assembly svg{display:block;width:100%;height:330px;background:#f6f9f7;border-radius:5px}.caption{font-size:14px;color:#526c6d}.tag{font-size:13px;letter-spacing:1px;color:#597978}input[type=range]{width:min(460px,70vw)}details{margin-top:12px;font-size:14px}footer{margin:32px 0;font-size:14px}@media(max-width:800px){.grid{grid-template-columns:1fr 1fr}.assembly{grid-template-columns:1fr}h1{font-size:27px}}@media(max-width:460px){main{padding:20px 14px}.grid{grid-template-columns:1fr}.art{height:175px}}
</style></head><body><main><a href="../../../../../icons.html">← 当前图标库</a><p class="tag">NEW FAMILY · FLAT SVG · v0.8</p><h1>PI3K–AKT–mTOR：8 个新图标。</h1><p>用轮廓和结构域区分蛋白。每个图标包含透明 PNG 原图、纯色 SVG、语义分区与可接近的边缘锚点。文字、磷酸化和 GDP/GTP 状态由组图单独添加。</p><div class="toolbar" aria-label="图标显示尺寸"><span>查看尺寸</span><button data-size="64" aria-pressed="false">64 px</button><button data-size="96" aria-pressed="false">96 px</button><button data-size="160" aria-pressed="true">160 px</button><a href="manifest.json">来源与锚点</a></div><div class="grid" id="icons"></div>
<h2>接触与组装预览</h2><p>拖动滑块，查看游离、靠近和结合。比较四组蛋白靠近和接触时的轮廓与位置。mTOR 面板各显示一个接触关系；完整 mTORC1 的二聚体组成不在此展示。</p><div class="toolbar"><label for="progress">组装进度</label><input id="progress" type="range" min="0" max="3" step="0.01" value="3"><button id="play">播放</button><output id="phase">结合</output></div><div class="assembly" id="assembly"></div><p class="caption">形态、接触面和速度用于机制教学，不表示原子几何、分子尺寸或实测结合动力学。RHEB 的尾部只提示膜定位，当前接触预览未绘制膜。</p><details><summary>参考与生成记录</summary><p>BioRender 公开通路预览只用于观察平面图示风格。未复制其素材。结构域和蛋白功能另按 RCSB 的结构元数据与对应原始论文摘要核对。每条记录区分“视觉观察”和“文本核对”。</p><p><a href="prompts.json">8 条完整生成提示词</a> · <a href="source-specifications.json">源图坐标与转换规格</a> · <a href="interfaces.json">接触轮廓与使用比例</a> · <a href="assembly-models.json">组装模型</a></p></details><footer>SVG 路径可编辑；语义填色支持改色。要让单个结构域独立运动，需要进一步绑定共享轮廓。</footer></main><script>/*ENGINE*/</script><script>
const ICONS=/*ICONS*/,MODELS=/*MODELS*/;
const byId=Object.fromEntries(ICONS.map(e=>[e.id,e]));
document.querySelector('#icons').innerHTML=ICONS.map(e=>`<article class="card"><div class="art"><img alt="${e.label}" src="data:image/svg+xml;base64,${btoa(unescape(encodeURIComponent(e.svg)))}"></div><h3>${e.label}</h3><p>${e.description_zh||e.description}</p><div class="links"><a href="${e.id}.svg" download>SVG ↓</a><a href="sources/${e.id}.png" download>PNG 原图 ↓</a></div><details><summary>结构域与参考</summary><p>${Object.keys(e.palette).filter(k=>k!=='outline').join(' · ')}</p>${e.scientific_references.map(r=>`<a href="${r.url}" target="_blank" rel="noopener">RCSB 结构记录 ↗</a>`).join('<br>')}</details></article>`).join('');
for(const b of document.querySelectorAll('[data-size]'))b.onclick=()=>{document.querySelectorAll('.art img').forEach(im=>{im.style.width=b.dataset.size+'px';im.style.height=b.dataset.size+'px'});document.querySelectorAll('[data-size]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))};
const cores=MODELS.map(m=>DomainMotion.make(m,ICONS));
document.querySelector('#assembly').innerHTML=MODELS.map((m,i)=>`<article class="card"><h3>${m.title}</h3><svg id="scene-${i}" role="img" aria-label="${m.title}接触预览" viewBox="${m.preview_viewBox.join(' ')}"></svg></article>`).join('');
function render(t){cores.forEach((core,i)=>{const frame=core.frame(t);let out='';for(const [id,p]of Object.entries(frame.poses)){const e=byId[core.entities[id].icon];let art=e.svg.replace(/<\\?xml[^>]*>/,'').replace(/<svg[^>]*>/,'').replace(/<\\/svg>\\s*$/,'').replaceAll(e.id,`scene${i}-${id}-${e.id}`);out+=`<g data-entity="${id}" transform="translate(${p.c}) rotate(${p.a*180/Math.PI}) scale(${p.s}) translate(-80 -80)">${art}</g>`}document.querySelector(`#scene-${i}`).innerHTML=out});document.querySelector('#phase').textContent=t<.01?'游离':t<2.1?'靠近':'结合'}
const slider=document.querySelector('#progress');let running=false,last=0;slider.oninput=()=>{running=false;document.querySelector('#play').textContent='播放';render(+slider.value)};
document.querySelector('#play').onclick=()=>{running=!running;last=performance.now();if(running&&+slider.value>=3)slider.value=0;document.querySelector('#play').textContent=running?'暂停':'播放';if(running)requestAnimationFrame(tick)};
function tick(now){if(!running)return;slider.value=Math.min(3,+slider.value+(now-last)/1000);last=now;render(+slider.value);if(+slider.value>=3){running=false;document.querySelector('#play').textContent='播放'}else requestAnimationFrame(tick)}render(3);
</script></body></html>'''
(f/'preview.html').write_text(template.replace('/*ENGINE*/',engine).replace('/*ICONS*/',json.dumps(icons,ensure_ascii=False)).replace('/*MODELS*/',json.dumps(models,ensure_ascii=False)))
print(f/'preview.html')
